# ---------------------------------------------------------------------------

def reset_tables():
    with engine.begin() as conn:
        conn.execute(text("""
            TRUNCATE TABLE
                activity_log, notes, reviews, payments, order_items,
                orders, products, customers
            RESTART IDENTITY CASCADE
        """))


def seed():
    reset_tables()
    db = SessionLocal()

    try:
        # --- Products ---
        product_rows = {}
        for p in PRODUCTS:
            row = Product(
                id=p["id"],
                name=p["name"],
                price=Decimal(str(p["price"])),
                category=p["category"],
            )
            db.add(row)
            product_rows[p["id"]] = row
        db.flush()

        # --- Customers ---
        customer_rows = {}
        for c in CUSTOMERS:
            row = Customer(
                id=c["id"],
                name=c["name"],
                phone=c["phone"],
                email=c["email"],
            )
            db.add(row)
            customer_rows[c["id"]] = row
        db.flush()

        # --- Orders ---
        order_rows = {}
        for o in ORDERS:
            row = Order(
                id=o["id"],
                customer_id=o["customer_id"],
                order_date=datetime.fromisoformat(o["order_date"]),
                total_amount=Decimal(str(o["total_amount"])),
                status=o["status"],
                order_type=o["order_type"],
            )
            db.add(row)
            order_rows[o["id"]] = row
        db.flush()

        # --- Order Items ---
        for oi in ORDER_ITEMS:
            db.add(OrderItem(
                id=oi["id"],
                order_id=oi["order_id"],
                product_id=oi["product_id"],
                quantity=oi["quantity"],
                unit_price=Decimal(str(oi["unit_price"])),
            ))
        db.flush()

        # --- Payments ---
        for p in PAYMENTS:
            db.add(Payment(
                id=p["id"],
                order_id=p["order_id"],
                amount=Decimal(str(p["amount"])),
                due_date=datetime.fromisoformat(p["due_date"]) if p.get("due_date") else None,
                paid_date=datetime.fromisoformat(p["paid_date"]) if p.get("paid_date") else None,
                status=p["status"],
            ))
        db.flush()

        # --- Reviews ---
        for r in REVIEWS:
            db.add(Review(
                id=r["id"],
                customer_id=r["customer_id"],
                order_id=r["order_id"],
                rating=r["rating"],
                comment=r.get("comment", ""),
                created_at=datetime.fromisoformat(r["created_at"]),
            ))

        db.commit()
        print(f"Seed complete:")
        print(f"  {len(PRODUCTS)} products")
        print(f"  {len(CUSTOMERS)} customers")
        print(f"  {len(ORDERS)} orders")
        print(f"  {len(ORDER_ITEMS)} order items")
        print(f"  {len(PAYMENTS)} payments")
        print(f"  {len(REVIEWS)} reviews")

        paid = sum(1 for p in PAYMENTS if p["status"] == "paid")
        overdue = sum(1 for p in PAYMENTS if p["status"] == "overdue")
        pending = sum(1 for p in PAYMENTS if p["status"] == "pending")
        print(f"  Payment split: {paid} paid / {overdue} overdue / {pending} pending")

    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


if __name__ == "__main__":
    seed()
